package com.seamware.consentmanager.config;

import io.micronaut.context.annotation.ConfigurationProperties;
import io.micronaut.core.annotation.Nullable;
import java.time.Duration;
import java.util.List;
import lombok.Getter;
import lombok.Setter;

/**
 * Root configuration properties for the Consent Manager application.
 *
 * <p>Binds properties under the {@code consent-manager} prefix from {@code application.yml} (or
 * environment variables) into typed Java fields. The accessors are generated by Lombok, so each
 * setting is documented once, on the field the deployment actually sets; Lombok runs before {@code
 * micronaut-inject-java} in {@code annotationProcessorPaths} so that the generated setters are
 * there to be bound.
 *
 * <p>Environment variable mapping:
 *
 * <ul>
 *   <li>{@code CONSENT_MANAGER_URL} &rarr; {@code consent-manager.url}
 *   <li>{@code CONTRACT_SERVICE_URL} &rarr; {@code consent-manager.contract-service.url}
 *   <li>{@code USERS_SEARCH_MAX_RESULTS} &rarr; {@code consent-manager.users.search-max-results}
 *   <li>{@code PARTICIPANTS_PAGE_DEFAULT_SIZE} &rarr; {@code
 *       consent-manager.participants.page-default-size}
 *   <li>{@code PARTICIPANTS_PAGE_MAX_SIZE} &rarr; {@code
 *       consent-manager.participants.page-max-size}
 * </ul>
 *
 * @see <a href="https://docs.micronaut.io/latest/guide/#configurationProperties">Micronaut
 *     Configuration Properties</a>
 */
@Getter
@Setter
@ConfigurationProperties("consent-manager")
public class ConsentManagerConfiguration {

    /**
     * Public base URL of this instance, bound to {@code CONSENT_MANAGER_URL}.
     *
     * <p>Defaulted in {@code application.yml} rather than here, since a deployment that gets it
     * wrong should fail against its own configuration.
     */
    private String url;

    /**
     * The Contract Service this instance reads contracts from, bound under {@code
     * consent-manager.contract-service}.
     *
     * <p>These keys are the single place each setting is named. {@code application.yml} forwards
     * them into the keys the framework reads - {@code micronaut.http.services.contract-service} for
     * the base URL and the two timeouts, {@code micronaut.caches.contracts} for the cache lifetime
     * - and the retry settings are resolved from them by the {@code @Retryable} placeholders on
     * {@code ContractServiceClient}. The fields here type and document that contract in one place;
     * only the URL is read from Java, where a failure has to name the upstream it failed against.
     */
    @Getter
    @Setter
    @ConfigurationProperties("contract-service")
    public static class ContractService {

        /** Longest a connection attempt may take when none is configured. */
        public static final Duration DEFAULT_CONNECT_TIMEOUT = Duration.ofSeconds(2);

        /** Longest a response may take to arrive when none is configured. */
        public static final Duration DEFAULT_READ_TIMEOUT = Duration.ofSeconds(5);

        /** Retries attempted after a failed fetch, when none is configured. */
        public static final int DEFAULT_RETRY_ATTEMPTS = 3;

        /** Pause before the first retry when none is configured. */
        public static final Duration DEFAULT_RETRY_DELAY = Duration.ofMillis(500);

        /** Factor each further retry delay is multiplied by when none is configured. */
        public static final double DEFAULT_RETRY_MULTIPLIER = 2.0;

        /** Longest a fetched contract is served from the cache when none is configured. */
        public static final Duration DEFAULT_CACHE_TTL = Duration.ofSeconds(60);

        /** Base URL of the Contract Service, bound to {@code CONTRACT_SERVICE_URL}. */
        private String url;

        /**
         * Longest a connection attempt may take, bound to {@code CONTRACT_SERVICE_CONNECT_TIMEOUT}.
         *
         * <p>Exceeding it is a retryable failure, not a bad contract.
         */
        private Duration connectTimeout = DEFAULT_CONNECT_TIMEOUT;

        /**
         * Longest one attempt may wait for a response, bound to {@code
         * CONTRACT_SERVICE_READ_TIMEOUT}.
         *
         * <p>Per attempt, not per fetch. A fetch is bounded by {@code (retry-attempts + 1) x
         * read-timeout} plus the growing retry pauses - about 23.5s at the defaults - and by twice
         * that when the ecosystem endpoint misses and the bilateral one is tried as well. Size a
         * caller's own timeout from that bound, not from this value.
         */
        private Duration readTimeout = DEFAULT_READ_TIMEOUT;

        /**
         * Retries after a failed fetch, bound to {@code CONTRACT_SERVICE_RETRY_ATTEMPTS}; one is
         * the floor, because {@code @Retryable} refuses a budget below it at the first call.
         *
         * <p>Counted after the initial attempt, as {@code @Retryable} does, so three retries are at
         * most four upstream requests. Only a 5xx or a transport failure is retried; a 4xx is a
         * defect retrying cannot fix and would only multiply the load on an upstream that already
         * refused.
         */
        private int retryAttempts = DEFAULT_RETRY_ATTEMPTS;

        /**
         * Pause before the first retry, bound to {@code CONTRACT_SERVICE_RETRY_DELAY}.
         *
         * <p>Together with the multiplier it bounds the total wait between attempts.
         */
        private Duration retryDelay = DEFAULT_RETRY_DELAY;

        /**
         * Factor each further retry delay grows by, bound to {@code
         * CONTRACT_SERVICE_RETRY_MULTIPLIER}; one makes every retry wait the same delay.
         */
        private double retryMultiplier = DEFAULT_RETRY_MULTIPLIER;

        /**
         * Longest a fetched contract is served from the cache, bound to {@code
         * CONTRACT_SERVICE_CACHE_TTL}.
         *
         * <p>Not a latency knob: a notice is generated from the cached document, so this is how
         * stale the contract behind a freshly published notice may be, and how long a contract
         * change can go unnoticed by a repeated generation. Keep it short.
         */
        private Duration cacheTtl = DEFAULT_CACHE_TTL;
    }

    /**
     * Reading of the catalog self-descriptions a contract only names, bound under {@code
     * consent-manager.self-description}.
     *
     * <p>Only a resolved retrieval reads these, and what it reads is an absolute URL taken from a
     * document this service does not own. The two guards here are what keeps that from being an
     * open proxy into the deployment's own network.
     *
     * <p>The timeouts are the Contract Service's: both are reads of an upstream catalog on the same
     * request path, and a second pair of knobs would only let them drift apart.
     */
    @Getter
    @Setter
    @ConfigurationProperties("self-description")
    public static class SelfDescription {

        /** Longest a fetched self-description is served from the cache when none is configured. */
        public static final Duration DEFAULT_CACHE_TTL = Duration.ofMinutes(10);

        /** Documents one resolved retrieval reads before it stops walking the catalog. */
        public static final int DEFAULT_MAX_DOCUMENTS = 50;

        /** Longest one resolved retrieval spends walking the catalog when none is configured. */
        public static final Duration DEFAULT_MAX_DURATION = Duration.ofSeconds(15);

        /**
         * Hosts a self-description may be fetched from, bound to {@code
         * SELF_DESCRIPTION_ALLOWED_HOSTS}; empty admits any host outside this network.
         *
         * <p>An entry also waives the private-address refusal for that host: naming a host here is
         * an operator's statement about their own network, and it outranks the address heuristic.
         * An empty list still refuses every loopback, link-local and private-range address.
         */
        private List<String> allowedHosts = List.of();

        /**
         * Documents one resolved retrieval reads before it gives up and reports the data section
         * unavailable, bound to {@code SELF_DESCRIPTION_MAX_DOCUMENTS}.
         *
         * <p>The walk is over lists this service does not author - the offerings a contract names
         * and the resources each offering names - so without a ceiling a single authenticated GET
         * fans out as far as whoever publishes them decides.
         */
        private int maxDocuments = DEFAULT_MAX_DOCUMENTS;

        /**
         * Longest one resolved retrieval spends walking the catalog before it gives up and reports
         * the data section unavailable, bound to {@code SELF_DESCRIPTION_MAX_DURATION}.
         *
         * <p>The companion of {@code max-documents}, and not a duplicate of it: a document ceiling
         * bounds how many reads a retrieval makes but not how long each one takes, so without this
         * the walk's worst case is the ceiling times the read timeout and a handful of concurrent
         * retrievals of one notice would hold the request pool for minutes.
         */
        private Duration maxDuration = DEFAULT_MAX_DURATION;

        /**
         * Whether a self-description may be read over plain {@code http}, bound to {@code
         * SELF_DESCRIPTION_ALLOW_PLAINTEXT_HTTP}.
         */
        private boolean allowPlaintextHttp;

        /**
         * Longest a fetched self-description is served from the cache, bound to {@code
         * SELF_DESCRIPTION_CACHE_TTL}.
         *
         * <p>Longer than the contract's may be: a catalog document describes a resource rather than
         * stating the terms a notice is published under, so staleness here costs a title and not a
         * legal statement.
         */
        private Duration cacheTtl = DEFAULT_CACHE_TTL;

        /**
         * Sets the allow-list, dropping the blank entries a configured-but-empty value leaves.
         *
         * <p>Written out rather than generated because {@code ${SELF_DESCRIPTION_ALLOWED_HOSTS:}}
         * resolves to the empty string when the variable is unset, which binds as a single blank
         * entry. That would make the list non-empty, and a non-empty list no real host is named in
         * refuses every URL - resolution would be dead in the default configuration.
         */
        public void setAllowedHosts(@Nullable List<String> allowedHosts) {
            this.allowedHosts =
                    allowedHosts == null
                            ? List.of()
                            : allowedHosts.stream()
                                    .filter(host -> host != null && !host.isBlank())
                                    .map(String::trim)
                                    .toList();
        }
    }

    /** Settings of the erasure path, bound under {@code consent-manager.erasure}. */
    @Getter
    @Setter
    @ConfigurationProperties("erasure")
    public static class Erasure {

        /**
         * Key of the HMAC an erased record carries instead of its identifier, bound to {@code
         * ERASURE_VERIFICATION_SECRET}.
         *
         * <p>Held by the operator, never by a participant and never in the database, so that only
         * the operator can confirm a candidate identifier against an erased record. Blank or unset
         * - the default - means erased records carry no verifier at all, and nothing can be
         * confirmed against them ever again. Changing it abandons every verifier written under the
         * previous one.
         */
        @Nullable private String verificationSecret;
    }

    /** Limits on the user directory, bound under {@code consent-manager.users}. */
    @Getter
    @Setter
    @ConfigurationProperties("users")
    public static class Users {

        /** Cap applied when none is configured; neither search nor lookup is paginated. */
        public static final int DEFAULT_SEARCH_MAX_RESULTS = 200;

        /** Entries one bulk registration may carry when none is configured. */
        public static final int DEFAULT_BULK_MAX_SIZE = 500;

        /**
         * Most users one search may return, bound to {@code USERS_SEARCH_MAX_RESULTS}; a value
         * below one would make every search answer empty.
         *
         * <p>The result is sorted by identifier before the cap applies, so truncation is
         * deterministic rather than whatever the database happened to return first.
         */
        private int searchMaxResults = DEFAULT_SEARCH_MAX_RESULTS;

        /**
         * Most entries one bulk registration may carry, bound to {@code USERS_BULK_MAX_SIZE}; a
         * value below one would make every bulk registration a bad request.
         *
         * <p>A larger batch is refused whole with {@code 400} before anything is written, since
         * entries are applied one at a time and an unbounded batch would hold a request open for as
         * long as the client cared to make it.
         */
        private int bulkMaxSize = DEFAULT_BULK_MAX_SIZE;
    }

    /** Paging of the participant directory, bound under {@code consent-manager.participants}. */
    @Getter
    @Setter
    @ConfigurationProperties("participants")
    public static class Participants {

        /** Records a directory page carries when the caller asks for no size. */
        public static final int DEFAULT_PAGE_DEFAULT_SIZE = 20;

        /** Most records a directory page may carry when no ceiling is configured. */
        public static final int DEFAULT_PAGE_MAX_SIZE = 100;

        /**
         * Page size applied when {@code GET /participants} names none, bound to {@code
         * PARTICIPANTS_PAGE_DEFAULT_SIZE}; a value below one would make every page answer empty.
         *
         * <p>Deliberately absent from the specification, which could not track a value configured
         * per deployment; the response reports the size it applied instead.
         */
        private int pageDefaultSize = DEFAULT_PAGE_DEFAULT_SIZE;

        /**
         * Most records one directory page may carry, bound to {@code PARTICIPANTS_PAGE_MAX_SIZE};
         * it caps the default too, since the clamp applies to that as well.
         *
         * <p>A larger requested size is clamped to this rather than refused, so raising or lowering
         * the ceiling never turns a caller's working request into a {@code 400}.
         */
        private int pageMaxSize = DEFAULT_PAGE_MAX_SIZE;
    }
}
